import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"周易闡真 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"周易闡真 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"classics/chanzhen/012.md","filePath":"classics/chanzhen/012.md"}'),s={name:"classics/chanzhen/012.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：泰，小往大來。吉，亨。則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。</p></blockquote><h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><p>初九：拔茅茹，以其匯，徵吉。</p><p>九二：包荒，用馮河，不遐遺。朋亡，得尚於中行。</p><p>九三：無平不陂，無往不復。艱貞無咎，勿恤其孚，於食有福。</p><p>六四：翩翩，不富以其鄰，不戒以孚。</p><p>六五：帝乙歸妹，以祉元吉。</p><p>上六：城復於隍。勿用師。自邑告命，貞吝。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：天地交，泰。後以財成天地之道，輔相天地之宜，以左右民。</p><p>財同裁。相音象。左音佐。右音佑。</p><p>泰者，通也。上坤地，下乾天，天氣自下而上升，地氣自上而下降，是天地陰陽之氣相交，萬物發生，泰之象也。</p><p>元后有見於此，知天地陰陽相交而萬物生，人之陰陽相交而萬化安，以之財成天地之道，輔相天地之宜焉。人秉天地陰陽五行之氣而生身，身中即具此陰陽五行之氣。此氣在人身中，發而為五德。五德其體，有自然之道，不待勉強，所謂率性之道也。後明五行相生之理，使仁義理智信一氣流行，裁成乎天地生人自然之道。五德其用，有當然之宜，不可偏執，所謂修道之教也。後明五行相剋之理，使仁義禮智信各得其當，輔相其天地賦人當然之宜。裁成其道，輔相其宜，凡以為通天下之志，成天下之務，以左右斯民，使人人皆以天地之道為道，以天地之宜為宜，保合太和，各正性命耳。噫!誰無天地之道?誰無天地之宜?特患不能裁成，不能輔相耳。果能裁成之，則先天可全；果能輔相之，則後天可化。先天全，後天化，其體自然，其用當然，五行一氣，五德混成，性命凝結，方且與天地同功用，與天地同長久，其泰為何如哉！</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>匯，音胃。馮，音馮副本。</p><p>泰者，通和之義。卦德上坤順，下乾健，陽健於內，陰順於外，健順如一，陰陽相應，故謂泰。此陰陽相交之卦，承上小畜而來。小畜一陰，而畜五陽，陰氣主事，陽氣不振，小於畜而不能大於畜，其行不通。通行之道，必須大小無傷，陰陽相當，陰順陽而陽統陰，陰陽和合，方能濟事。故泰之為道，小往大來，吉而得亨也。</p><p>小者陰也，大者陽也。小往則陰順，大來則陽健。陽健於內，陰順於外，先天漸復，後天漸化，可以造於純陽無陰之地。於理得吉，於行行亨，但致泰之道，有火候、有工程，進之退之，各有其時。不失其時，健而順行，以順養健，未泰者而能致，已泰者而能保，由了命而了性，自有為而無為，完成大道，理有可決也。</p><p>初九，一陽潛生，諸陽皆有動機，如拔茅之茹根以及匯葉也。致泰者，乘此一陽發現，而即下手修為，漸採漸煉，由微而著，未有陽不健而陰不順者，故曰“徵吉”。此剛而乘時以致泰也。</p><p>九二，剛健中正，通權達變，是以包荒用馮河，不遐遺朋亡也。包荒者，度量寬宏，用柔也。馮河者，志氣勇敢，用剛也。不遐遺者，靜觀密察，柔之至。朋亡者，閒邪存誠，剛之至。剛中有柔，柔中有剛，文烹武煉，左之右之，無不宜之，得尚於中行矣。此剛柔相濟以致泰也。</p><p>九三，三陽已足，陽極必陰，泰極必否，如無平不陂，無往不復。當此之時，須要知進知退，艱難守貞，防危慮險，方無得而復失之咎。既無其咎，功成人間，名標天上，且食天福，享壽無窮，何憂恤之有？此剛極守正以保泰也。</p><p>六四，當陽極交陰之際，不能防危慮險，一陰潛生，群陰皆動，如翩翩不富以其鄰，無待相戒而孚合，金丹已得而復失。此以柔傷剛而失泰也。</p><p>六五，當正泰之時，以陰養陽，陽氣凝結，如帝乙歸妹，以祉及於臣下，陰戀陽而陽戀陰，陰陽同氣，自有天然真火，爐中赫赫長紅，雖在已泰而不失初泰之吉。此以柔養剛而全泰也。</p><p>上六，在泰之終，順之極，只知泰之順，不知泰之逆，不防於早，必敗於終，如城傾而復於隍矣。當此之時，好事已去，難以為力，故曰“勿用行師”。凶事已臨，後悔不及，故曰“自邑告命，貞吝”。此柔而不知早於保泰也。</p><p>然則致泰保泰，各有其時；有為無為，各有其法。隨時而行，依法而作，健所當健，順所當順，健以致泰，順以保泰，未泰者能泰，已泰者長泰，何患不吉不亨，大道不成乎！</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
